-- Option integration tests exercise effects, persistence and combat boundaries.
local A=GMMLegion735;local s=A.frames.Settings;local bags=A.frames.Bags
local function check(ok,label)assert(ok,label);MOCK.passed=MOCK.passed+1 end
MOCK.combat=false;MOCK:Drain();bags:Hide();WorldMapFrame:Hide();s:Show()
check(s.checks.questCompanion and s.checks.hideCombat and s.checks.autoLoot and s.checks.autoSortBags and s.checks.unifiedBags and s.checks.autoSellJunk,'all legacy settings present')
check(GMMLegionDB.unifiedBags and GMMLegionDB.questCompanion and not GMMLegionDB.autoSellJunk,'safe first-run options and opt-in sale')
A:SetOption('windowScale',.7);check(math.abs(A.frames.Utilities:GetScale()-.7)<.001,'window size immediately affects existing windows')
A:SetOption('scale',1.2);check(A.mini:GetScale()==1.2 and s.miniScale.value:GetText()=='120%','minibar scale persists and displays actual value')
s:Hide();s:Show();check(s.windowScale.value:GetText()=='70%','settings reopen from saved state')
A:SetOption('windowScale',9);check(GMMLegionDB.windowScale==1.1,'window scale clamps input')
local screenWidth=UIParent:GetWidth();UIParent:SetWidth(1026);A:SetOption('windowScale',1);local fitted=A.frames.Utilities:GetScale();A:SetOption('windowScale',.95)
check(A.frames.Utilities:GetScale()<fitted,'first minus step changes scale even when screen fitting already shrinks the window');UIParent:SetWidth(screenWidth)
A:SetOption('autoLoot',true);check(GetCVar('autoLootDefault')=='1'and s.checks.autoLoot:GetChecked(),'auto loot writes and reads actual client cvar')
SetCVar('autoLootDefault','0');check(not s.checks.autoLoot:GetChecked(),'external game option changes refresh visible checkbox')
A:SetOption('questCompanion',false);WorldMapFrame:Show();check(not A.frames.Quests:IsShown(),'disabled helper stays hidden on map open')
A:SetOption('questCompanion',true);check(A.frames.Quests:IsShown(),'enabling helper attaches to already-open map')
WorldMapFrame:Hide();check(not A.frames.Quests:IsShown(),'quest helper follows map close')
WorldMapFrame:Show();check(A.frames.Quests:IsShown(),'enabled helper returns with map');WorldMapFrame:Hide()
A:SetOption('hideCombat',true);check(MOCK.stateDrivers[A.UI.combatWindows]=='[combat] hide; show','secure driver handles combat visibility')
A:SetOption('hideCombat',false);check(not MOCK.stateDrivers[A.UI.combatWindows]and A.UI.combatWindows:IsShown(),'disable hides no panels and unregisters driver')
check(A.mini:GetParent()==UIParent and A.frames.Utilities:GetParent()==A.UI.combatWindows,'combat hiding never hides minibar shortcuts')
A:SetOption('unifiedBags',false);local n=MOCK.nativeBagsToggled or 0;A:ToggleBags()
check(not bags:IsShown()and MOCK.nativeBagsToggled==n+1,'OFF opens native bags rather than custom UI')
MOCK:Fire('MERCHANT_SHOW');MOCK:Drain();check(not bags:IsShown(),'OFF does not replace native merchant bags')
A:SetOption('unifiedBags',true);A:ToggleBags();check(bags:IsShown(),'ON immediately restores unified bag opening')
A:SetOption('autoSortBags',true);check(GMMLegionDB.autoSortBags and s.checks.autoSortBags:GetChecked(),'automatic sort and settings stay synchronized')
bags.sort:Click('RightButton');check(not GMMLegionDB.autoSortBags and not s.checks.autoSortBags:GetChecked()and not bags.sortJob,'toolbar disables running sort and refreshes settings')
GMMLegionDB.points.main={'CENTER',99,99};GMMLegionDB.points.Bags={'CENTER',90,90};GMMLegionDB.windowLocked=true;GMMLegionDB.bagLocked=true
A:RestoreWindowPositions();check(not GMMLegionDB.points.main and not GMMLegionDB.points.Bags and not GMMLegionDB.windowLocked and not GMMLegionDB.bagLocked,'restore positions clears coordinates and movement locks')
local saved=GMMLegionDB.windowScale;MOCK.combat=true;A:SetOption('windowScale',.6)
check(GMMLegionDB.windowScale==saved,'combat blocks setting changes without modifying saved value')
MOCK.target='Enemy';MOCK.targetIsPlayer=false;MOCK:ResetSent();A.mini.buttons.kill:Click();check(MOCK.sent[1][1]=='.die'and MOCK.target=='Enemy','kill shortcut sends once in combat without changing target')
MOCK:ResetSent();A.mini.buttons.god:Click();check(MOCK.target=='TestGM'and MOCK.sent[1][1]:match('^%.cheat god '),'hardware self shortcut works during combat')
MOCK:ResetSent();A.mini.buttons.fly:Click();check(MOCK.sent[1][1]:match('^%.gm fly '),'flight shortcut is no longer blanket-blocked in combat')
MOCK:ResetSent();A.mini.buttons.revive:Click();check(MOCK.sent[1][1]=='.revive','revive shortcut sends in combat')
MOCK:ResetSent();A.mini.buttons.kill:Click();check(#MOCK.sent==0,'self instant death remains blocked')
MOCK.combat=false;A:SetOption('windowScale',1);A:SetOption('scale',1);A:SetOption('hideCombat',true);MOCK:Drain()
check(#GMMLegionDiagnostics.errors==0,table.concat(GMMLegionDiagnostics.errors,'\n'))
